#include "terminal.h"
#include "../../graphics/graphics.h"
#define OUT_CAP 4096u
#define LINE_CAP 256u
static desktop_window_t g_window; static char g_output[OUT_CAP],g_line[LINE_CAP];
static uint32_t g_output_length,g_line_length; static uint8_t g_dragging; static int32_t g_drag_x,g_drag_y;
static uint8_t hit(int32_t px,int32_t py,int32_t x,int32_t y,int32_t w,int32_t h){return (uint8_t)(px>=x&&py>=y&&px<x+w&&py<y+h);}
void terminal_init(uint32_t sw,uint32_t sh){g_output_length=0;g_output[0]=0;g_line_length=0;g_line[0]=0;g_dragging=0;g_drag_x=0;g_drag_y=0;g_window.x=16;g_window.y=48;g_window.w=(int32_t)((sw*2u)/3u);if(g_window.w<220)g_window.w=220;g_window.h=(int32_t)(sh/2u);if(g_window.h<140)g_window.h=140;}
desktop_window_t *terminal_window(void){return &g_window;}
void terminal_append(const char *s){while(s&&*s){if(g_output_length+1u>=sizeof(g_output)){for(uint32_t i=0;i<sizeof(g_output)/2u;i++)g_output[i]=g_output[i+sizeof(g_output)/2u];g_output_length=sizeof(g_output)/2u;}g_output[g_output_length++]=*s++;}g_output[g_output_length]=0;}
const char *terminal_line(void){return g_line;} uint32_t terminal_line_length(void){return g_line_length;}
void terminal_clear_line(void){g_line_length=0;g_line[0]=0;} void terminal_clear_output(void){g_output_length=0;g_output[0]=0;}
uint8_t terminal_handle_char(char c){if(c=='\b'){if(!g_line_length)return 0;g_line[--g_line_length]=0;return 1;}if(c=='\n')return 2;if(c<32||c>126||g_line_length+1u>=sizeof(g_line))return 0;g_line[g_line_length++]=c;g_line[g_line_length]=0;return 1;}
terminal_click_result_t terminal_handle_click(int32_t x,int32_t y){int32_t wx=g_window.x,wy=g_window.y,ww=g_window.w,wh=g_window.h;if(hit(x,y,wx+ww-24,wy+5,20,20)){g_dragging=0;return TERMINAL_CLICK_CLOSE;}if(hit(x,y,wx,wy,ww,30)){g_dragging=1;g_drag_x=x-wx;g_drag_y=y-wy;return TERMINAL_CLICK_FOCUS;}if(hit(x,y,wx,wy,ww,wh))return TERMINAL_CLICK_FOCUS;return TERMINAL_CLICK_NONE;}
void terminal_pointer_move(int32_t x,int32_t y){if(g_dragging){g_window.x=x-g_drag_x;g_window.y=y-g_drag_y;}} void terminal_pointer_release(void){g_dragging=0;}
void terminal_draw(const terminal_render_context_t *ctx){if(!ctx||!ctx->window||!ctx->draw_chrome)return;const desktop_window_t *win=ctx->window;if(win->w<40||win->h<60)return;int32_t x=win->x,y=win->y,w=win->w,h=win->h;ctx->draw_chrome(win,"Terminal","VexOS Shell",ctx->focused,1,0);gfx_draw_string((uint32_t)(x+14),(uint32_t)(y+40),"VEXOS TERMINAL  /  LOCAL SESSION",0x7FA4C7u);uint32_t px=(uint32_t)x+10u,py=(uint32_t)y+56u,pw=w>20?(uint32_t)w-20u:1u,ph=h>94?(uint32_t)h-94u:1u;gfx_blend_round_rect(px,py,pw,ph,5u,0x091321u,255);gfx_draw_rect(px+1u,py+1u,pw-2u,1u,0x1C344Du);uint32_t tx=px+12u,ty=py+12u,cols=pw>24u?(pw-24u)/8u:0u,rows=ph>20u?(ph-20u)/10u:0u;if(cols&&rows){uint32_t cap=cols*rows,start=g_output_length>cap?g_output_length-cap:0u,cx=0,cy=0;for(uint32_t i=start;i<g_output_length&&cy<rows;i++){char ch=g_output[i];if(ch=='\n'){cx=0;cy++;continue;}if(cx<cols&&ch>=32&&ch<=126)gfx_draw_glyph(tx+cx*8u,ty+cy*10u,(uint8_t)ch,0xD7E7F7u);cx++;if(cx>=cols){cx=0;cy++;}}}uint32_t iy=(uint32_t)(y+h-30);gfx_blend_round_rect((uint32_t)(x+10),iy,(uint32_t)(w-20),24u,5u,0x1A2C40u,255);gfx_draw_rect((uint32_t)(x+18),iy+1u,(uint32_t)(w-36),1u,0x35516Du);gfx_draw_string((uint32_t)(x+22),iy+8u,">",0x79E0B0u);gfx_draw_string((uint32_t)(x+38),iy+8u,g_line,0xF1F6FCu);if(ctx->focused&&((ctx->tick/30u)%2u==0u))gfx_draw_rect((uint32_t)(x+38)+g_line_length*8u,iy+8u,7u,8u,0x79E0B0u);}
